  DIALOGS.accountSwitchExpired=p=>dialogShell({title:'这个账号需要重新登录',body:`${note('暂时无法切换到 '+esc(p.target)+'。当前账号仍然保持登录，资料和输入没有变化。','warn')}<p class="hint">重新登录成功后再切换，或者先返回继续使用当前账号。</p>`,footer:`${closeBtn}<button class="btn btn-primary" onclick="A.accountRelogin(${esc(JSON.stringify(p.target))})">重新登录</button>`});
  const previousDeepLink=A.deepLink;
  A.deepLink=function(url){if(!String(url).startsWith('xingmang://pay'))return previousDeepLink(url);let id='';try{id=new URL(url).searchParams.get('order')||'';}catch(_){}const found=findOrder(id);if(!found){A.toast('没有找到对应订单，请到“我的订单”选择需要查询的订单。','warn');return;}A.accountOrder(id);A.accountOrderQuery(id);};
