  XM.accountCharge=function(amountUSD,ownerName=S.user?.name,options={}){const record=st().records[ownerName],amount=Number(amountUSD);if(!record||!Number.isFinite(amount)||amount<=0)return {ok:false,error:'暂时无法读取账户额度，请重新登录后再试。'};const active=record.subscriptions.filter(s=>s.status==='active'&&(!s.expiresAt||s.expiresAt>=datePlus(0))&&s.quota>s.used);const subscriptionLeft=active.reduce((n,s)=>n+s.quota-s.used,0),pref=record.preference||'subscription_first',balance=record.user.balance??0;const available=pref==='balance_only'?balance:pref==='subscription_only'?subscriptionLeft:balance+subscriptionLeft;if(available+1e-8<amount)return {ok:false,error:pref==='subscription_only'?'订阅额度不足。请购买订阅或更改扣费偏好。':pref==='balance_only'?'账户余额不足。请充值或更改扣费偏好。':'可用额度不足。请充值或购买订阅后再试。'};let remaining=amount,fromBalance=0,fromSubscription=0;const spendBalance=()=>{const take=Math.min(remaining,balance);fromBalance=take;remaining=roundUSD(remaining-take);};const spendSubscription=()=>{const take=Math.min(remaining,subscriptionLeft);fromSubscription=take;remaining=roundUSD(remaining-take);};if(pref==='balance_first'||pref==='balance_only'){spendBalance();if(pref!=='balance_only')spendSubscription();}else{spendSubscription();if(pref!=='subscription_only')spendBalance();}const result={ok:true,amountUSD:amount,balanceUSD:roundUSD(fromBalance),subscriptionUSD:roundUSD(fromSubscription),billing:fromSubscription>0?(fromBalance>0?'mixed':'subscription'):'balance'};if(options.preview)return result;record.user.balance=roundUSD(balance-fromBalance);let subSpend=fromSubscription;for(const sub of active){const take=Math.min(subSpend,sub.quota-sub.used);sub.used=roundUSD(sub.used+take);subSpend=roundUSD(subSpend-take);if(subSpend<=0)break;}S.accounts=S.accounts.map(u=>u.name===ownerName?{...record.user}:u);return result;};
  const chargeAccount = XM.accountCharge;
  XM.accountCharge = function(amountUSD,ownerName=S.user?.name,options={}){const result=chargeAccount(amountUSD,ownerName,options);result.source=result.billing||null;result.message=result.ok?(result.source==='subscription'?'已使用订阅额度':result.source==='mixed'?'已使用订阅额度与账户余额':'已使用账户余额'):result.error;if(result.ok&&!options.preview){const record=st().records[ownerName];record.charges ||= [];record.charges.push({id:uid('charge'),owner:ownerName,when:stamp(),amountUSD:result.amountUSD,balanceUSD:result.balanceUSD,subscriptionUSD:result.subscriptionUSD,source:result.source});}return result;};
